import{_ as e,o as i,c as a,a5 as n}from"./chunks/framework.a5no_H3L.js";const h=JSON.parse('{"title":"Redis 客户端连接与故障处理","description":"本页面向需要把 Redis 接入生产应用的后端开发人员，说明如何选择客户端能力、设置连接生命周期，并处理超时、故障转移和集群重定向。内容以 Redis 7.4.11 为基准；客户端库的配置名称不同，但需要解决的问题相同。","frontmatter":{},"headers":[],"relativePath":"redis/04-operations/chapter-01-client-connection.md","filePath":"redis/04-operations/chapter-01-client-connection.md"}'),l={name:"redis/04-operations/chapter-01-client-connection.md"};function c(d,t,r,s,o,p){return i(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="redis-客户端连接与故障处理" tabindex="-1" data-src-line="1" data-src-file="redis/04-operations/chapter-01-client-connection.md">Redis 客户端连接与故障处理 <a class="header-anchor" href="#redis-客户端连接与故障处理" aria-label="Permalink to &quot;Redis 客户端连接与故障处理&quot;">​</a></h1><p data-src-line="3" data-src-file="redis/04-operations/chapter-01-client-connection.md">本页面向需要把 Redis 接入生产应用的后端开发人员，说明如何选择客户端能力、设置连接生命周期，并处理超时、故障转移和集群重定向。内容以 Redis 7.4.11 为基准；客户端库的配置名称不同，但需要解决的问题相同。</p><p data-src-line="5" data-src-file="redis/04-operations/chapter-01-client-connection.md">连接管理的目标不是让连接永远不断，而是在故障发生时有界地等待、准确地判断结果，并在能力允许时恢复。权威来源见<a href="https://redis.io/docs/latest/develop/reference/clients/" target="_blank" rel="noreferrer">Redis 客户端处理说明</a>、<a href="https://redis.io/docs/latest/develop/reference/sentinel-clients/" target="_blank" rel="noreferrer">Sentinel 客户端规范</a>和 <a href="https://redis.io/docs/latest/develop/reference/cluster-spec/" target="_blank" rel="noreferrer">Redis Cluster 规范</a>。</p><h2 id="topology" tabindex="-1" data-src-line="7" data-src-file="redis/04-operations/chapter-01-client-connection.md">1. 确定连接拓扑 <a class="header-anchor" href="#topology" aria-label="Permalink to &quot;1. 确定连接拓扑 {#topology}&quot;">​</a></h2><p data-src-line="9" data-src-file="redis/04-operations/chapter-01-client-connection.md">客户端必须知道应用连接的是单实例、Sentinel 还是 Cluster。三者对地址发现、读写位置和重连行为的要求不同。</p><table tabindex="0"><thead data-src-line="11" data-src-file="redis/04-operations/chapter-01-client-connection.md"><tr data-src-line="11" data-src-file="redis/04-operations/chapter-01-client-connection.md"><th style="text-align:left;">拓扑</th><th style="text-align:left;">客户端必须具备的能力</th><th style="text-align:left;">故障后的关键动作</th></tr></thead><tbody data-src-line="13" data-src-file="redis/04-operations/chapter-01-client-connection.md"><tr data-src-line="13" data-src-file="redis/04-operations/chapter-01-client-connection.md"><td style="text-align:left;">单实例</td><td style="text-align:left;">连接地址、超时、连接池、健康检查</td><td style="text-align:left;">有界重连；超过错误预算后快速失败</td></tr><tr data-src-line="14" data-src-file="redis/04-operations/chapter-01-client-connection.md"><td style="text-align:left;">Sentinel</td><td style="text-align:left;">使用 Sentinel 地址和服务名发现主节点</td><td style="text-align:left;">重新查询主节点，验证角色，不复用旧主地址</td></tr><tr data-src-line="15" data-src-file="redis/04-operations/chapter-01-client-connection.md"><td style="text-align:left;">Cluster</td><td style="text-align:left;">维护槽到节点的映射，处理重定向和拓扑刷新</td><td style="text-align:left;">跟随 <code>MOVED</code>，按规范处理 <code>ASK</code>，刷新槽映射</td></tr></tbody></table><p data-src-line="17" data-src-file="redis/04-operations/chapter-01-client-connection.md">不要把服务器 IP 写死后用于 Sentinel 服务。Sentinel 规范要求客户端在每次重连时重新解析服务地址，并通过 <code>ROLE</code> 等命令确认目标确实是主节点。Cluster 客户端收到 <code>MOVED</code> 后应向指定节点重发查询；槽迁移期间收到 <code>ASK</code> 时，应按客户端协议完成 <code>ASKING</code> 后再发送原命令。</p><p data-src-line="19" data-src-file="redis/04-operations/chapter-01-client-connection.md">多 Key 命令还要先检查拓扑约束：</p><ul data-src-line="21" data-src-file="redis/04-operations/chapter-01-client-connection.md"><li data-src-line="21" data-src-file="redis/04-operations/chapter-01-client-connection.md">单实例和 Sentinel 不限制不同 Key 的槽位置。</li><li data-src-line="22" data-src-file="redis/04-operations/chapter-01-client-connection.md">Cluster 中的多 Key 操作必须位于同一哈希槽；相关 Key 使用一致的哈希标签。</li><li data-src-line="23" data-src-file="redis/04-operations/chapter-01-client-connection.md">读副本时要接受复制延迟，写请求必须由客户端或代理路由到可写主节点。</li></ul><p data-src-line="25" data-src-file="redis/04-operations/chapter-01-client-connection.md">机制分别见<a href="./../03-high-availability/chapter-03-sentinel.html">哨兵</a>和<a href="./../03-high-availability/chapter-04-cluster.html">集群</a>。</p><h2 id="client-selection" tabindex="-1" data-src-line="27" data-src-file="redis/04-operations/chapter-01-client-connection.md">2. 选择客户端能力 <a class="header-anchor" href="#client-selection" aria-label="Permalink to &quot;2. 选择客户端能力 {#client-selection}&quot;">​</a></h2><p data-src-line="29" data-src-file="redis/04-operations/chapter-01-client-connection.md">选型时先验证故障行为，再比较 API 是否顺手。至少检查以下能力：</p><ul data-src-line="31" data-src-file="redis/04-operations/chapter-01-client-connection.md"><li data-src-line="31" data-src-file="redis/04-operations/chapter-01-client-connection.md">支持目标部署形态，尤其是 Sentinel 服务发现或 Cluster 槽路由。</li><li data-src-line="32" data-src-file="redis/04-operations/chapter-01-client-connection.md">能分别设置连接、读取和写入超时，而不是只有一个模糊的总超时。</li><li data-src-line="33" data-src-file="redis/04-operations/chapter-01-client-connection.md">连接池具有最大连接数、空闲连接和等待队列上限，能够暴露等待和拒绝指标。</li><li data-src-line="34" data-src-file="redis/04-operations/chapter-01-client-connection.md">重试次数有上限，退避带随机抖动，并能限制一段时间内的总重试预算。</li><li data-src-line="35" data-src-file="redis/04-operations/chapter-01-client-connection.md">能刷新拓扑，不把一次连接失败或 <code>MOVED</code> 当作永久地址变化。</li><li data-src-line="36" data-src-file="redis/04-operations/chapter-01-client-connection.md">提供连接数、池等待时间、命令延迟、错误类型和拓扑刷新事件。</li><li data-src-line="37" data-src-file="redis/04-operations/chapter-01-client-connection.md">支持应用使用的 RESP 版本、认证、TLS 和所需命令。</li></ul><p data-src-line="39" data-src-file="redis/04-operations/chapter-01-client-connection.md">RESP 3 是 Redis 6 引入的协议版本，能返回更丰富的回复类型；RESP 2 仍是许多客户端和部署的默认兼容路径。选择协议前应确认服务端、代理和客户端三者一致，不要仅根据协议版本判断客户端优劣。</p><p data-src-line="41" data-src-file="redis/04-operations/chapter-01-client-connection.md">客户端选型应通过一次重启、一次 Sentinel 故障转移和一次 Cluster 槽迁移演练验证。只用 <code>PING</code> 成功作为验收条件，会漏掉最重要的拓扑刷新和重连问题。</p><h2 id="lifecycle" tabindex="-1" data-src-line="43" data-src-file="redis/04-operations/chapter-01-client-connection.md">3. 设置连接生命周期 <a class="header-anchor" href="#lifecycle" aria-label="Permalink to &quot;3. 设置连接生命周期 {#lifecycle}&quot;">​</a></h2><p data-src-line="45" data-src-file="redis/04-operations/chapter-01-client-connection.md">不同客户端对配置的命名不同，但都应覆盖以下生命周期。</p><table tabindex="0"><thead data-src-line="47" data-src-file="redis/04-operations/chapter-01-client-connection.md"><tr data-src-line="47" data-src-file="redis/04-operations/chapter-01-client-connection.md"><th style="text-align:left;">配置</th><th style="text-align:left;">作用</th><th style="text-align:left;">配置过大的风险</th><th style="text-align:left;">配置过小的风险</th></tr></thead><tbody data-src-line="49" data-src-file="redis/04-operations/chapter-01-client-connection.md"><tr data-src-line="49" data-src-file="redis/04-operations/chapter-01-client-connection.md"><td style="text-align:left;">连接超时</td><td style="text-align:left;">限制建立 TCP 连接的等待时间</td><td style="text-align:left;">故障时请求积压</td><td style="text-align:left;">网络抖动时误判成功</td></tr><tr data-src-line="50" data-src-file="redis/04-operations/chapter-01-client-connection.md"><td style="text-align:left;">读取超时</td><td style="text-align:left;">限制等待响应的时间</td><td style="text-align:left;">故障恢复变慢，线程或协程被占用</td><td style="text-align:left;">高峰期把慢请求当作失败</td></tr><tr data-src-line="51" data-src-file="redis/04-operations/chapter-01-client-connection.md"><td style="text-align:left;">连接池上限</td><td style="text-align:left;">限制同时持有的连接</td><td style="text-align:left;">打满服务端 <code>maxclients</code> 和文件描述符</td><td style="text-align:left;">池等待时间成为主要延迟</td></tr><tr data-src-line="52" data-src-file="redis/04-operations/chapter-01-client-connection.md"><td style="text-align:left;">最大空闲时间</td><td style="text-align:left;">回收长期不用的连接</td><td style="text-align:left;">保留过多无用连接</td><td style="text-align:left;">频繁建连和 TLS 握手</td></tr><tr data-src-line="53" data-src-file="redis/04-operations/chapter-01-client-connection.md"><td style="text-align:left;">重试上限</td><td style="text-align:left;">限制单次操作的额外尝试</td><td style="text-align:left;">故障被放大，恢复变慢</td><td style="text-align:left;">短暂抖动直接暴露给调用方</td></tr></tbody></table><p data-src-line="55" data-src-file="redis/04-operations/chapter-01-client-connection.md">服务端 <code>timeout</code> 只会在空闲达到指定秒数后断开客户端连接，不能代替客户端读取超时。TCP keepalive 用于探测连接是否仍然存在，也不能保证应用已经收到响应。</p><p data-src-line="57" data-src-file="redis/04-operations/chapter-01-client-connection.md">连接池大小应从应用并发和池等待指标推导，不直接套用“每 100 QPS 一个连接”之类的固定公式。所有客户端的池上限、监控连接和管理连接之和，应低于服务端 <code>maxclients</code>，并为突发流量保留余量：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Σ(应用连接池上限) + 监控/管理连接 + 协议开销 &lt; maxclients × 安全水位</span></span></code></pre></div><p data-src-line="63" data-src-file="redis/04-operations/chapter-01-client-connection.md">还应检查进程和操作系统的文件描述符上限。服务端在无法接受新连接时会返回连接数超限错误并立即关闭连接；此时增加客户端重试只会提高服务端压力。</p><h2 id="retry" tabindex="-1" data-src-line="65" data-src-file="redis/04-operations/chapter-01-client-connection.md">4. 限制重试和请求放大 <a class="header-anchor" href="#retry" aria-label="Permalink to &quot;4. 限制重试和请求放大 {#retry}&quot;">​</a></h2><p data-src-line="67" data-src-file="redis/04-operations/chapter-01-client-connection.md">重试前要区分“请求肯定没有执行”和“结果未知”。Redis 返回超时只说明客户端没有及时收到响应，不表示服务器没有执行命令。</p><table tabindex="0"><thead data-src-line="69" data-src-file="redis/04-operations/chapter-01-client-connection.md"><tr data-src-line="69" data-src-file="redis/04-operations/chapter-01-client-connection.md"><th style="text-align:left;">结果</th><th style="text-align:left;">是否可直接重试</th><th style="text-align:left;">原因与处理</th></tr></thead><tbody data-src-line="71" data-src-file="redis/04-operations/chapter-01-client-connection.md"><tr data-src-line="71" data-src-file="redis/04-operations/chapter-01-client-connection.md"><td style="text-align:left;">尚未发送请求</td><td style="text-align:left;">通常可以</td><td style="text-align:left;">按退避策略重连并重新发送</td></tr><tr data-src-line="72" data-src-file="redis/04-operations/chapter-01-client-connection.md"><td style="text-align:left;">已发送，响应未知</td><td style="text-align:left;">需要业务判断</td><td style="text-align:left;"><code>INCR</code>、<code>LPUSH</code>、<code>XADD</code> 等命令可能已经成功</td></tr><tr data-src-line="73" data-src-file="redis/04-operations/chapter-01-client-connection.md"><td style="text-align:left;"><code>NOAUTH</code>、<code>WRONGPASS</code>、<code>NOPERM</code></td><td style="text-align:left;">不应重试</td><td style="text-align:left;">先修复认证或 ACL 配置</td></tr><tr data-src-line="74" data-src-file="redis/04-operations/chapter-01-client-connection.md"><td style="text-align:left;"><code>CROSSSLOT</code></td><td style="text-align:left;">不应重试</td><td style="text-align:left;">修改 Key 分组或哈希标签</td></tr><tr data-src-line="75" data-src-file="redis/04-operations/chapter-01-client-connection.md"><td style="text-align:left;"><code>MOVED</code>、<code>ASK</code></td><td style="text-align:left;">由集群客户端处理</td><td style="text-align:left;">更新路由后按协议重发，不手工无限循环</td></tr><tr data-src-line="76" data-src-file="redis/04-operations/chapter-01-client-connection.md"><td style="text-align:left;"><code>READONLY</code></td><td style="text-align:left;">重新发现拓扑</td><td style="text-align:left;">写请求此前被发到了只读副本</td></tr><tr data-src-line="77" data-src-file="redis/04-operations/chapter-01-client-connection.md"><td style="text-align:left;"><code>LOADING</code></td><td style="text-align:left;">有界重试</td><td style="text-align:left;">仅在业务允许的恢复窗口内退避等待</td></tr><tr data-src-line="78" data-src-file="redis/04-operations/chapter-01-client-connection.md"><td style="text-align:left;"><code>OOM command not allowed</code></td><td style="text-align:left;">默认不重试</td><td style="text-align:left;">先确认容量、淘汰策略和业务降级</td></tr></tbody></table><p data-src-line="80" data-src-file="redis/04-operations/chapter-01-client-connection.md">对结果未知且不可重复的写入，应由业务使用幂等键、结果核对或补偿流程处理。客户端无法替应用判断一次 <code>INCR</code> 到底执行了零次、一次还是两次。</p><p data-src-line="82" data-src-file="redis/04-operations/chapter-01-client-connection.md">重试采用指数退避并加入随机抖动，同时满足三个边界：</p><ol data-src-line="84" data-src-file="redis/04-operations/chapter-01-client-connection.md"><li data-src-line="84" data-src-file="redis/04-operations/chapter-01-client-connection.md">单次操作的总等待时间不超过业务超时。</li><li data-src-line="85" data-src-file="redis/04-operations/chapter-01-client-connection.md">单位时间内的总重试量不超过故障预算。</li><li data-src-line="86" data-src-file="redis/04-operations/chapter-01-client-connection.md">连续失败达到阈值后打开熔断，让调用方快速失败或走降级路径。</li></ol><p data-src-line="88" data-src-file="redis/04-operations/chapter-01-client-connection.md">连接池耗尽时，等待本身也是延迟。池等待应有独立上限；不能在应用线程中无限等待一个永远不会恢复的 Redis。</p><h2 id="failure" tabindex="-1" data-src-line="90" data-src-file="redis/04-operations/chapter-01-client-connection.md">5. 区分常见连接故障 <a class="header-anchor" href="#failure" aria-label="Permalink to &quot;5. 区分常见连接故障 {#failure}&quot;">​</a></h2><p data-src-line="92" data-src-file="redis/04-operations/chapter-01-client-connection.md">先按错误类型分类，再决定重试、修复配置或切换拓扑。</p><table tabindex="0"><thead data-src-line="94" data-src-file="redis/04-operations/chapter-01-client-connection.md"><tr data-src-line="94" data-src-file="redis/04-operations/chapter-01-client-connection.md"><th style="text-align:left;">现象</th><th style="text-align:left;">优先检查</th><th style="text-align:left;">处理方向</th></tr></thead><tbody data-src-line="96" data-src-file="redis/04-operations/chapter-01-client-connection.md"><tr data-src-line="96" data-src-file="redis/04-operations/chapter-01-client-connection.md"><td style="text-align:left;">连接被拒绝</td><td style="text-align:left;">服务状态、监听地址、防火墙</td><td style="text-align:left;">修复网络或路由，不提高重试次数</td></tr><tr data-src-line="97" data-src-file="redis/04-operations/chapter-01-client-connection.md"><td style="text-align:left;">连接建立后很快断开</td><td style="text-align:left;"><code>maxclients</code>、空闲超时、代理空闲策略</td><td style="text-align:left;">调整连接预算和空闲参数</td></tr><tr data-src-line="98" data-src-file="redis/04-operations/chapter-01-client-connection.md"><td style="text-align:left;">认证失败</td><td style="text-align:left;">ACL 用户名、密码注入、默认用户状态</td><td style="text-align:left;">轮换错误凭据，确认实际登录身份</td></tr><tr data-src-line="99" data-src-file="redis/04-operations/chapter-01-client-connection.md"><td style="text-align:left;">权限不足</td><td style="text-align:left;">ACL Key 模式和命令规则</td><td style="text-align:left;">按最小权限补规则，不直接授予全部命令</td></tr><tr data-src-line="100" data-src-file="redis/04-operations/chapter-01-client-connection.md"><td style="text-align:left;">写请求返回 <code>READONLY</code></td><td style="text-align:left;">Sentinel/Cluster 拓扑缓存</td><td style="text-align:left;">重新发现可写节点并刷新连接</td></tr><tr data-src-line="101" data-src-file="redis/04-operations/chapter-01-client-connection.md"><td style="text-align:left;">延迟和池等待同时升高</td><td style="text-align:left;">阻塞命令、大 Key、池容量</td><td style="text-align:left;">查看慢日志和连接池指标</td></tr><tr data-src-line="102" data-src-file="redis/04-operations/chapter-01-client-connection.md"><td style="text-align:left;">集群持续重定向</td><td style="text-align:left;">槽映射、网络地址公布、代理配置</td><td style="text-align:left;">检查 <code>CLUSTER NODES</code> 和客户端拓扑刷新</td></tr></tbody></table><p data-src-line="104" data-src-file="redis/04-operations/chapter-01-client-connection.md">具体错误见<a href="./../reference/errors.html">常见错误与连接问题</a>。排障时同时观察应用侧指标和服务端的 <code>INFO clients</code>、<code>CLIENT LIST</code>、<code>SLOWLOG</code>，不要只看进程是否存活。</p><h2 id="observability" tabindex="-1" data-src-line="106" data-src-file="redis/04-operations/chapter-01-client-connection.md">6. 观察连接状态 <a class="header-anchor" href="#observability" aria-label="Permalink to &quot;6. 观察连接状态 {#observability}&quot;">​</a></h2><p data-src-line="108" data-src-file="redis/04-operations/chapter-01-client-connection.md">应用侧至少记录：</p><ul data-src-line="110" data-src-file="redis/04-operations/chapter-01-client-connection.md"><li data-src-line="110" data-src-file="redis/04-operations/chapter-01-client-connection.md">连接成功、失败和当前活跃连接数。</li><li data-src-line="111" data-src-file="redis/04-operations/chapter-01-client-connection.md">连接池最大连接数、空闲连接数、等待任务数和等待时间。</li><li data-src-line="112" data-src-file="redis/04-operations/chapter-01-client-connection.md">连接、读取、重试和拓扑刷新各自的耗时与失败次数。</li><li data-src-line="113" data-src-file="redis/04-operations/chapter-01-client-connection.md">按错误类型区分的结果，不把所有失败合并成一个“Redis 异常”。</li><li data-src-line="114" data-src-file="redis/04-operations/chapter-01-client-connection.md">故障转移前后旧连接的释放速度和新拓扑的生效时间。</li></ul><p data-src-line="116" data-src-file="redis/04-operations/chapter-01-client-connection.md">服务端可从 <code>INFO clients</code> 查看 <code>connected_clients</code>、<code>blocked_clients</code> 和 <code>maxclients</code>。<code>CLIENT LIST</code> 用于查看单个连接的地址、空闲时间和发送请求数；连接很多时应限制输出规模，并避免把包含应用名称或地址的日志长期留存到不受控位置。</p><p data-src-line="118" data-src-file="redis/04-operations/chapter-01-client-connection.md">连接相关指标的告警不应只针对连接总数。更常见的故障信号是池等待时间上升、重试率上升、拓扑刷新失败，以及连接数达到上限前的持续增长。</p><h2 id="verification" tabindex="-1" data-src-line="120" data-src-file="redis/04-operations/chapter-01-client-connection.md">7. 验证连接方案 <a class="header-anchor" href="#verification" aria-label="Permalink to &quot;7. 验证连接方案 {#verification}&quot;">​</a></h2><p data-src-line="122" data-src-file="redis/04-operations/chapter-01-client-connection.md">上线前至少完成以下测试：</p><ol data-src-line="124" data-src-file="redis/04-operations/chapter-01-client-connection.md"><li data-src-line="124" data-src-file="redis/04-operations/chapter-01-client-connection.md">拒绝一个错误地址，确认连接超时受控，调用方没有无上限等待。</li><li data-src-line="125" data-src-file="redis/04-operations/chapter-01-client-connection.md">重启 Redis，确认连接池清理失效连接，新连接能够恢复。</li><li data-src-line="126" data-src-file="redis/04-operations/chapter-01-client-connection.md">执行 Sentinel 故障转移，确认客户端重新发现主节点，不继续向旧地址写入。</li><li data-src-line="127" data-src-file="redis/04-operations/chapter-01-client-connection.md">执行 Cluster 槽迁移，确认 <code>MOVED</code> 和 <code>ASK</code> 被正确处理，应用无持续重定向循环。</li><li data-src-line="128" data-src-file="redis/04-operations/chapter-01-client-connection.md">切换 ACL 凭据，确认旧连接失效后按计划重建，新凭据不写入日志。</li><li data-src-line="129" data-src-file="redis/04-operations/chapter-01-client-connection.md">制造高并发池等待，确认等待超时、降级和告警符合预期。</li></ol><p data-src-line="131" data-src-file="redis/04-operations/chapter-01-client-connection.md">验收记录应包含业务超时、池上限、重试预算、故障恢复时间，以及每项测试的预期结果。没有经过故障演练的默认配置，只能证明连接成功，不能证明故障可控。</p><h2 id="_8-参考资料" tabindex="-1" data-src-line="133" data-src-file="redis/04-operations/chapter-01-client-connection.md">8. 参考资料 <a class="header-anchor" href="#_8-参考资料" aria-label="Permalink to &quot;8. 参考资料&quot;">​</a></h2><ul data-src-line="135" data-src-file="redis/04-operations/chapter-01-client-connection.md"><li data-src-line="135" data-src-file="redis/04-operations/chapter-01-client-connection.md">Redis 官方：<a href="https://redis.io/docs/latest/develop/reference/clients/" target="_blank" rel="noreferrer">Client handling</a></li><li data-src-line="136" data-src-file="redis/04-operations/chapter-01-client-connection.md">Redis 官方：<a href="https://redis.io/docs/latest/develop/reference/sentinel-clients/" target="_blank" rel="noreferrer">Sentinel client specification</a></li><li data-src-line="137" data-src-file="redis/04-operations/chapter-01-client-connection.md">Redis 官方：<a href="https://redis.io/docs/latest/develop/reference/cluster-spec/" target="_blank" rel="noreferrer">Redis Cluster specification</a></li></ul>',44)])])}const m=e(l,[["render",c]]);export{h as __pageData,m as default};
